from lib import *
S = SS('l73')
steps = [
    step("这台 git(2.54.0)对 10 个任务名都接受:gc、commit-graph、prefetch、loose-objects、incremental-repack、pack-refs、reflog-expire、rerere-gc、worktree-prune、geometric-repack;对一个编造的名字 bogus 则报 error: 'bogus' is not a valid task。“可用”只表示名字被认可、命令没有报错,不代表这个任务在该仓库里会做出改变。", t=tl(S(1)), mark=lidx(S(1), 'bogus'), done=lidx(S(1), 'gc  ', 'geometric-repack', 'worktree-prune'), kv=KV([['任务名', '10 个都被接受'], ['不认识的名字', "error: '…' is not a valid task"], ['含义', '只是名字合法,不保证有改动']], ['任务名'])),
    step("把同一个仓库(8 个提交、664 个松散对象、4 个松散 ref)复制几份,每份只跑一个任务:loose-objects 之后 pack 数变成 1,但松散对象仍是 664;再跑一次 loose-objects,松散对象才变成 0(第一次打包,下一次才清理已打包的松散对象)。commit-graph 只写了提交图。pack-refs 把 4 个松散 ref 变成 0 个并生成 packed-refs。incremental-repack 在没有 pack 的仓库里什么也没改变。geometric-repack 把松散对象变成 0、生成 1 个 pack 和 midx。gc 一次完成:松散对象 0、1 个 pack、提交图、packed-refs,但没有 midx。", t=tl(S(2)), mark=lidx(S(2), 'loose-objects', '第 2 次', 'incremental-repack'), done=lidx(S(2), 'commit-graph', 'pack-refs', 'geometric-repack', 'gc  '), kv=KV([['loose-objects', '第一次打包,第二次才清理松散对象'], ['incremental-repack', '没有 pack 时无事可做'], ['geometric-repack', '松散对象 + 1 个 pack + midx'], ['gc', '一次做完大多数,没有 midx']], ['loose-objects'])),
    step("prefetch:远程新增了分支 newwork。运行 git maintenance run --task=prefetch 之前,refs/remotes 下有 origin/HEAD、b1、b2、main;之后多了 refs/prefetch/remotes/origin/* 四条(b1、b2、main、newwork),refs/remotes 一条没变,本地分支也没变。随后真正的 git fetch 更新了 refs/remotes,而 refs/prefetch 下的四条仍在。prefetch 把远程的对象预先下载到本地(没有测下一次 fetch 因此节省的时间)。", t=tl(S(3)), mark=lidx(S(3), '(prefetch 之后)'), done=lidx(S(3), '(prefetch 之前)', '之后真的 git fetch'), kv=KV([['prefetch', '下载到 refs/prefetch/<远程>/'], ['refs/remotes', '不动'], ['随后 git fetch', 'refs/remotes 才更新']], ['prefetch'])),
    step("不带 --task 时的任务由 maintenance.strategy 决定。不设置(手动运行的默认):pack-refs、reflog expire、repack --cruft、multi-pack-index write、commit-graph write --split、worktree prune、rerere gc;strategy=gc:pack-refs、reflog expire、git gc、repack --cruft、prune、worktree prune、rerere gc;strategy=geometric:repack --geometric=2 --write-midx 取代 gc,并有 multi-pack-index 与 commit-graph;strategy=incremental:手动运行时同样走 gc 那一套;写成 bogus 则 fatal: unknown maintenance strategy。", t=tl(S(4)), mark=lidx(S(4), 'strategy (不设置)', 'strategy gc:', 'strategy geometric:', 'strategy incremental:'), done=lidx(S(4), 'git gc --quiet', 'git repack -d -l --geometric=2', 'bogus'), kv=KV([['手动默认', 'geometric 风格的一组任务'], ['gc', '走 git gc'], ['incremental', '手动运行同样走 gc'], ['未知取值', 'fatal: unknown maintenance strategy']], ['手动默认'])),
    step("--auto 只在达到阈值时才运行任务。commit-graph.auto(默认 100):99 个不在提交图里的提交,git maintenance run --auto --task=commit-graph 什么也没做;100 个,写了提交图。loose-objects.auto(默认 100):全仓库 99 个松散对象什么也没做,100 个打包了;改成 loose-objects.auto=10 之后,9 个什么也没做,10 个打包了。阈值是“达到(≥)”而不是“超过”。", t=tl(S(5)), mark=lidx(S(5), '100 个提交', '全仓库 100 个', '全仓库 10 个'), done=lidx(S(5), '99 个提交', '全仓库 99 个', '全仓库 9 个'), b=bars([['99 个提交', 0, '什么也没做'], ['100 个提交', 1, '写了提交图'], ['99 个松散对象', 0, '什么也没做'], ['100 个松散对象', 1, '打包了']], 1, mark=[1, 3], done=[0, 2]), kv=KV([['commit-graph.auto', '默认 100 个提交,达到才写'], ['loose-objects.auto', '默认 100 个松散对象,达到才打包'], ['比较', '≥ 阈值']], ['比较'])),
    step("配置:全局 maintenance.auto 是实验环境的设置(false)。给 commit-graph 与 loose-objects 设置 enabled=true、给 commit-graph 设置 schedule=daily 之后,git config --get-regexp 能看到这四项;此时不带参数的 git maintenance run 比默认多了一条 git prune-packed(loose-objects 任务),其余与不设置时相同。maintenance.<任务>.enabled 控制是否运行,schedule 控制 --schedule 模式下的频率。", t=tl(S(6)), mark=lidx(S(6), 'maintenance.commit-graph.enabled', 'maintenance.loose-objects.enabled', 'maintenance.commit-graph.schedule', 'prune-packed'), done=lidx(S(6), 'maintenance.auto false'), kv=KV([['<任务>.enabled', '不带 --task 时是否运行'], ['<任务>.schedule', '--schedule 时的频率'], ['效果', '在策略之上增减任务']], ['<任务>.enabled'])),
]
A = mkarti('l73', 73, 'Git,maintenance,gc,commit-graph,prefetch,loose-objects,strategy,真实验证,动画演示',
    '实测 git maintenance:10 个任务名各自改变仓库的什么(loose-objects 两次才清理松散对象、pack-refs、commit-graph、geometric-repack、gc);prefetch 把远程分支下载到 refs/prefetch;maintenance.strategy 的四种取值实际启动的子命令;--auto 的阈值(commit-graph.auto 与 loose-objects.auto 默认 100,达到才运行);maintenance.<任务>.enabled 的效果。',
    'git maintenance 把“后台整理仓库”拆成一个个任务。每个任务到底改了仓库的什么?不指定任务时会跑哪些?--auto 的阈值怎么算?这篇每个任务单独跑一遍,记录前后的松散对象、pack、提交图、ref 的变化,再用 GIT_TRACE 看各个 strategy 实际启动了哪些子命令。',
    [('10 个', 'git 2.54.0 认识的 maintenance 任务名数量'), ('100', 'commit-graph.auto 与 loose-objects.auto 的默认阈值:99 不动,100 才运行'), ('2 次', 'loose-objects 要运行两次,第一次打包,第二次才清理松散对象')],
    [('有哪些任务', '<p>gc、commit-graph、prefetch、loose-objects、incremental-repack、pack-refs、reflog-expire、rerere-gc、worktree-prune、geometric-repack 这 10 个名字在这台 git 上都可以用 <code>--task=</code> 指定,不认识的名字报错。</p>'),
     ('每个任务改变了什么', '<p>用同一个仓库的副本每次只跑一个任务:<code>loose-objects</code> 先把松散对象打包,下一次才清理它们;<code>commit-graph</code> 写提交图;<code>pack-refs</code> 把松散 ref 收进 packed-refs;<code>geometric-repack</code> 打包并写 midx;<code>gc</code> 一次做完大部分工作;没有 pack 时 <code>incremental-repack</code> 无事可做。</p>'),
     ('prefetch', '<p><code>prefetch</code> 把远程的分支下载到 <code>refs/prefetch/&lt;远程&gt;/</code>,不改动 <code>refs/remotes</code> 和本地分支,它把远程的新对象提前下载好;下一次 <code>git fetch</code> 因此节省多少没有测。</p>'),
     ('strategy', '<p>不带 <code>--task</code> 时,<code>maintenance.strategy</code> 决定任务集合。手动运行默认是 geometric 风格;<code>gc</code> 与手动运行的 <code>incremental</code> 走 <code>git gc</code>;写错取值直接报 fatal。</p>'),
     ('--auto 的阈值', '<p><code>--auto</code> 让每个任务先判断是否达到阈值:提交图任务数不在提交图里的提交(默认 100),松散对象任务数全仓库的松散对象(默认 100),都是达到才运行。</p>'),
     ('配置', '<p><code>maintenance.&lt;任务&gt;.enabled</code> 在策略的基础上增减任务,<code>maintenance.&lt;任务&gt;.schedule</code> 决定 <code>--schedule</code> 模式下的频率。</p>')],
    steps,
    [ENV_I_GIT + '。任务名的“可用”来自对每个名字执行 git maintenance run --task=<名>;各任务的前后状态来自同一个仓库的副本;子命令来自 GIT_TRACE 的 run_command 行(过滤了 pack-objects);实验环境的全局配置里 maintenance.auto=false',
     '没有验证:git maintenance start / register 与后台调度(launchd);--schedule 的小时、每天、每周触发;gc 任务在 gc.auto 阈值上的行为;incremental-repack 在已有多个 pack 时的批量大小;prefetch 在 refs/prefetch 下旧引用何时被清理;is-needed 子命令的退出码语义;大仓库下各任务的耗时;并发运行时的锁文件'],
    'git maintenance 的任务')
